// Data types formerly generated by prost-build from castore.proto.
// Now plain Rust structs with serde derives, serialized with postcard.
use bytes::Bytes;
use serde::{Deserialize, Serialize};

/// A Directory can contain Directory, File or Symlink entries.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Directory {
    pub directories: Vec<DirectoryEntry>,
    pub files: Vec<FileEntry>,
    pub symlinks: Vec<SymlinkEntry>,
}

impl Default for Directory {
    fn default() -> Self {
        Self {
            directories: Vec::new(),
            files: Vec::new(),
            symlinks: Vec::new(),
        }
    }
}

/// A DirectoryEntry represents a directory.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct DirectoryEntry {
    
    pub name: Bytes,
    
    pub digest: Bytes,
    pub size: u64,
}

/// A FileEntry represents a regular or executable file.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct FileEntry {
    
    pub name: Bytes,
    
    pub digest: Bytes,
    pub size: u64,
    pub executable: bool,
}

/// A SymlinkEntry represents a symbolic link.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct SymlinkEntry {
    
    pub name: Bytes,
    
    pub target: Bytes,
}

/// An Entry is either a DirectoryEntry, FileEntry or SymlinkEntry.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Entry {
    pub entry: Option<entry::Entry>,
}

pub mod entry {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum Entry {
        Directory(super::DirectoryEntry),
        File(super::FileEntry),
        Symlink(super::SymlinkEntry),
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct StatBlobRequest {
    
    pub digest: Bytes,
    pub send_chunks: bool,
    pub send_bao: bool,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct StatBlobResponse {
    pub chunks: Vec<stat_blob_response::ChunkMeta>,
    
    pub bao: Bytes,
}

impl Default for StatBlobResponse {
    fn default() -> Self {
        Self {
            chunks: Vec::new(),
            bao: Bytes::new(),
        }
    }
}

pub mod stat_blob_response {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub struct ChunkMeta {
        
        pub digest: Bytes,
        pub size: u64,
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct ReadBlobRequest {
    
    pub digest: Bytes,
}

/// Represents some bytes of a blob, sent in chunks.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct BlobChunk {
    
    pub data: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct PutBlobResponse {
    
    pub digest: Bytes,
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct GetDirectoryRequest {
    pub recursive: bool,
    pub by_what: Option<get_directory_request::ByWhat>,
}

pub mod get_directory_request {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum ByWhat {
        Digest(Bytes),
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct PutDirectoryResponse {
    
    pub root_digest: Bytes,
}
